export type I18nKey = string;

interface I18nContextValue {
  language: LanguageCode;
  setLanguage: (language: LanguageCode) => void;
  t: (key: I18nKey) => string;
}

const I18nContext = createContext<I18nContextValue | null>(null);

const FALLBACK_I18N_CONTEXT: I18nContextValue = {
  language: "en",
  setLanguage: () => undefined,
  t: (key) => (COPY.en as Record<string, string>)[key] ?? key,
};

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<LanguageCode>("en");

  useEffect(() => {
    let active = true;
    void getAppSettings()
      .then((settings) => {
        if (active && settings.language) setLanguageState(settings.language);
      })
      .catch(() => undefined);
    return () => {
      active = false;
    };
  }, []);

  const setLanguage = useCallback((next: LanguageCode) => {
    setLanguageState(next);
    void saveAppSettings({ language: next }).catch(() => undefined);
  }, []);

  const value = useMemo<I18nContextValue>(
    () => ({
      language,
      setLanguage,
      t: (key) => {
        const copy = COPY[language] as Record<string, string>;
        return copy[key] ?? COPY.en[key as keyof typeof COPY.en] ?? EXTRA_COPY[key]?.[language] ?? EXTRA_COPY[key]?.en ?? key;
      },
    }),
    [language, setLanguage],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  return useContext(I18nContext) ?? FALLBACK_I18N_CONTEXT;
}
